"""Extend the CPU controller with certified epoch planning.

Validates the version 3 request, runs the bundled CPU model evaluators,
compiles the sampled probability table and plans certified feature-window
exports jointly across reserved service slots and finite token inventory.
The response contains the schedule, exact objective values, a feasible
circulation, residual potentials and (for coverage below one) a next-ratio
infeasibility cut.
"""
import json
from collections import deque
from fractions import Fraction

import metrics
import probability
from solver import Dinic, MCF

MAX_INPUT = 16 * 1024 * 1024

EPOCH_KEYS = {'model', 'class_values', 'stats', 'bucket', 'slots', 'flows',
              'groups', 'windows'}


def _pairs_hook(items):
    d = {}
    for k, v in items:
        if k in d:
            raise ValueError('duplicate key')
        d[k] = v
    return d


def _reject_constant(v):
    raise ValueError('nonfinite constant')


def _walk_ok(data):
    """Reject booleans/floats anywhere and container depth over 64."""
    stack = [(data, 1)]
    while stack:
        node, d = stack.pop()
        t = type(node)
        if t is dict:
            if d > 64:
                return False
            for k, v in node.items():
                stack.append((v, d + 1))
        elif t is list:
            if d > 64:
                return False
            for v in node:
                stack.append((v, d + 1))
        elif t is bool or t is float:
            return False
        elif t is not int and t is not str:
            return False
    return True


def _int(x, lo, hi):
    return type(x) is int and lo <= x <= hi


def _validate_case(c):
    if type(c) is not dict:
        return None
    if set(c) != EPOCH_KEYS:
        return None
    model = c['model']
    if type(model) is not str or model not in ('cnn', 'rnn'):
        return None
    cv = c['class_values']
    if type(cv) is not list or len(cv) != 7:
        return None
    for x in cv:
        if not _int(x, 1, 1000):
            return None
    stats = c['stats']
    if type(stats) is not list or len(stats) != 3:
        return None
    for x in stats:
        if not _int(x, 1, 10 ** 9):
            return None
    bucket = c['bucket']
    if type(bucket) is not list or len(bucket) != 2:
        return None
    if not _int(bucket[0], 1, 512):
        return None
    if not _int(bucket[1], 0, bucket[0]):
        return None
    slots = c['slots']
    if type(slots) is not list or not 1 <= len(slots) <= 256:
        return None
    prev_t = -1
    for row in slots:
        if type(row) is not list or len(row) != 3:
            return None
        t, cap, ref = row
        if not _int(t, 0, 10 ** 12) or t <= prev_t:
            return None
        if not _int(cap, 0, 512):
            return None
        if not _int(ref, 0, 512):
            return None
        prev_t = t
    if slots[0][2] != 0:
        return None
    groups = c['groups']
    if type(groups) is not list or not 0 <= len(groups) <= 32:
        return None
    G = len(groups)
    for row in groups:
        if type(row) is not list or len(row) != 2:
            return None
        p, ce = row
        if not (type(p) is int and (p == -1 or 0 <= p < G)):
            return None
        if not _int(ce, 0, 512):
            return None
    state = [0] * G
    for g in range(G):
        chain = []
        u = g
        while u != -1 and state[u] == 0:
            state[u] = 1
            chain.append(u)
            u = groups[u][0]
        if u != -1 and state[u] == 1:
            return None
        for v in chain:
            state[v] = 2
    flows = c['flows']
    if type(flows) is not list or not 1 <= len(flows) <= 32:
        return None
    F = len(flows)
    for row in flows:
        if type(row) is not list or len(row) != 4:
            return None
        t, ce, g, lab = row
        if not _int(t, 1, 64):
            return None
        if not _int(ce, t, 512):
            return None
        if not (type(g) is int and (g == -1 or 0 <= g < G)):
            return None
        if not _int(lab, 0, 6):
            return None
    windows = c['windows']
    if type(windows) is not list or not 0 <= len(windows) <= 512:
        return None
    for row in windows:
        if type(row) is not list or len(row) != 8:
            return None
        f, ready, exp, T, C, draw, prio, feats = row
        if not _int(f, 0, F - 1):
            return None
        if not _int(ready, 0, 10 ** 12):
            return None
        if not _int(exp, ready, 10 ** 12):
            return None
        if not _int(T, 1, 65535):
            return None
        if not _int(C, 1, 320):
            return None
        if not _int(draw, 0, 65535):
            return None
        if not _int(prio, 1, 1000):
            return None
        if type(feats) is not list or len(feats) != 9:
            return None
        for fr in feats:
            if type(fr) is not list or len(fr) != 2:
                return None
            if not _int(fr[0], 0, 1500):
                return None
            if not _int(fr[1], 0, 2560):
                return None
    return {'model': model, 'class_values': cv, 'stats': stats, 'bucket': bucket,
            'slots': slots, 'flows': flows, 'groups': groups, 'windows': windows}


def _validate(data):
    if type(data) is not dict or set(data) != {'version', 'cases'}:
        return None
    if not _int(data['version'], 3, 3):
        return None
    cases = data['cases']
    if type(cases) is not list or not 0 <= len(cases) <= 8:
        return None
    out = []
    total = 0
    for c in cases:
        r = _validate_case(c)
        if r is None:
            return None
        total += len(r['windows'])
        if total > 1024:
            return None
        out.append(r)
    return out


def _predict(model, windows):
    J = len(windows)
    if J == 0:
        return []
    feats = [w[7] for w in windows]
    labels = [0] * J
    if model == 'cnn':
        import testcnnonnx as evaluator
    else:
        import testrnnonnx as evaluator
    preds = evaluator.evaluate_model_single_pass(feats, labels)
    return [int(p) for p in preds]


def _plan(c, preds, thresholds):
    """Solve one epoch; returns the RESULT dict (without reports)."""
    slots = c['slots']
    flows = c['flows']
    groups = c['groups']
    windows = c['windows']
    class_values = c['class_values']
    B, I = c['bucket']
    S = len(slots)
    J = len(windows)
    F = len(flows)
    G = len(groups)

    times = [r[0] for r in slots]
    scaps = [r[1] for r in slots]
    refills = [r[2] for r in slots]
    W = 1 + J * times[-1]
    value = [windows[j][6] * class_values[preds[j]] for j in range(J)]
    ready = [w[1] for w in windows]
    expires = [w[2] for w in windows]
    flow_of = [w[0] for w in windows]
    passes = [windows[j][5] < thresholds[j] for j in range(J)]
    target = [r[0] for r in flows]
    ceilf = [r[1] for r in flows]
    grpf = [r[2] for r in flows]
    parent = [r[0] for r in groups]
    ceilg = [r[1] for r in groups]

    def node_a(s):
        return 2 + 3 * s

    def node_b(s):
        return 3 + 3 * s

    def node_e(s):
        return 4 + 3 * s

    def node_w(j):
        return 2 + 3 * S + j

    def node_z(f):
        return 2 + 3 * S + J + f

    def node_h(g):
        return 2 + 3 * S + J + F + g

    K = 2 + 3 * S + J + F + G
    ZN = 1

    eligible = []
    for s in range(S):
        ts = times[s]
        for j in range(J):
            if passes[j] and ready[j] <= ts <= expires[j]:
                eligible.append((s, j))
    E = len(eligible)

    # ---- arc list in the normative output order ----
    arc_u = []
    arc_v = []
    arc_h = []
    arc_c = []
    for s in range(S):
        arc_u.append(0)
        arc_v.append(node_a(s))
        arc_h.append(I if s == 0 else refills[s])
        arc_c.append(0)
        arc_u.append(node_a(s))
        arc_v.append(node_b(s))
        arc_h.append(B)
        arc_c.append(0)
        if s + 1 < S:
            arc_u.append(node_b(s))
            arc_v.append(node_a(s + 1))
            arc_h.append(B)
            arc_c.append(0)
        arc_u.append(node_b(s))
        arc_v.append(node_e(s))
        arc_h.append(scaps[s])
        arc_c.append(0)
    chain_end = len(arc_u)
    e_start = chain_end
    for s, j in eligible:
        arc_u.append(node_e(s))
        arc_v.append(node_w(j))
        arc_h.append(1)
        arc_c.append((times[s] - ready[j]) - value[j] * W)
    e_end = len(arc_u)
    w_start = e_end
    for j in range(J):
        arc_u.append(node_w(j))
        arc_v.append(node_z(flow_of[j]))
        arc_h.append(1)
        arc_c.append(0)
    w_end = len(arc_u)
    f_start = w_end
    for f in range(F):
        tgt = node_h(grpf[f]) if grpf[f] >= 0 else ZN
        arc_u.append(node_z(f))
        arc_v.append(tgt)
        arc_h.append(ceilf[f])
        arc_c.append(0)
    f_end = len(arc_u)
    g_start = f_end
    for g in range(G):
        tgt = node_h(parent[g]) if parent[g] >= 0 else ZN
        arc_u.append(node_h(g))
        arc_v.append(tgt)
        arc_h.append(ceilg[g])
        arc_c.append(0)
    g_end = len(arc_u)
    zr_idx = g_end
    arc_u.append(ZN)
    arc_v.append(0)
    arc_h.append(J)
    arc_c.append(0)
    M = len(arc_u)

    # ---- feasibility oracle over the circulation with lower bounds ----
    def check_feasible(lf):
        dinic = Dinic(K + 2)
        ss, tt = K, K + 1
        sigma = [0] * K
        for idx in range(M):
            lo = lf[idx - f_start] if f_start <= idx < f_end else 0
            u = arc_u[idx]
            v = arc_v[idx]
            dinic.add(u, v, arc_h[idx] - lo)
            sigma[u] += lo
            sigma[v] -= lo
        demand = 0
        for v in range(K):
            if sigma[v] > 0:
                dinic.add(ss, v, sigma[v])
                demand += sigma[v]
            elif sigma[v] < 0:
                dinic.add(v, tt, -sigma[v])
        flow = dinic.max_flow(ss, tt)
        return flow == demand, dinic, ss

    def lf_for(r):
        p = r.numerator
        q = r.denominator
        return [(p * target[f] + q - 1) // q for f in range(F)]

    # ---- maximal coverage over the public Rset ----
    rset = sorted(set(Fraction(k, target[f])
                      for f in range(F) for k in range(target[f] + 1)))
    lo = 0
    hi = len(rset) - 1
    best = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        okf, _, _ = check_feasible(lf_for(rset[mid]))
        if okf:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    r_star = rset[best]
    lf = lf_for(r_star)
    sum_l = sum(lf)

    # ---- min-cost allocation at the reported coverage ----
    SS, TT = K, K + 1
    mcf = MCF(K + 2)
    fwd = [0] * M
    for idx in range(chain_end):
        fwd[idx] = mcf.add_edge(arc_u[idx], arc_v[idx], arc_h[idx], 0, 0)
    for idx in range(e_start, e_end):
        fwd[idx] = mcf.add_edge(arc_u[idx], arc_v[idx], 1, 0, arc_c[idx])
    for idx in range(w_start, w_end):
        fwd[idx] = mcf.add_edge(arc_u[idx], arc_v[idx], 1, 0, 0)

    pi = [0] * (K + 2)
    if sum_l > 0:
        mcf.add_edge(SS, 0, sum_l, 0, 0)
        for f in range(F):
            if lf[f] > 0:
                mcf.add_edge(node_z(f), TT, lf[f], 0, 0)
        pi = mcf.spfa_pi(pi)
        pushed = 0
        while pushed < sum_l:
            dist, prevv, preve = mcf.dijkstra(SS, pi)
            if dist[TT] is None:
                raise RuntimeError('mandatory flow unreachable')
            for v in range(K + 2):
                if dist[v] is not None:
                    pi[v] += dist[v]
            amt = mcf.path_bottleneck(SS, TT, prevv, preve)
            mcf.push_path(SS, TT, prevv, preve, amt)
            pushed += amt

    subtree_l = [0] * G
    for f in range(F):
        if lf[f]:
            g = grpf[f]
            while g >= 0:
                subtree_l[g] += lf[f]
                g = parent[g]
    for f in range(F):
        idx = f_start + f
        x_init = lf[f]
        fwd[idx] = mcf.add_edge(arc_u[idx], arc_v[idx],
                                arc_h[idx] - x_init, x_init, 0)
    for g in range(G):
        idx = g_start + g
        x_init = subtree_l[g]
        fwd[idx] = mcf.add_edge(arc_u[idx], arc_v[idx],
                                arc_h[idx] - x_init, x_init, 0)

    pi = mcf.spfa_pi(pi)
    while True:
        dist, prevv, preve = mcf.dijkstra(0, pi)
        if dist[1] is None:
            break
        actual = dist[1] + pi[1] - pi[0]
        if actual >= 0:
            break
        for v in range(K + 2):
            if dist[v] is not None:
                pi[v] += dist[v]
        amt = mcf.path_bottleneck(0, 1, prevv, preve)
        mcf.push_path(0, 1, prevv, preve, amt)

    # ---- extract flows, assignment and objective values ----
    x = [arc_h[idx] - mcf.cap[fwd[idx]] for idx in range(M)]
    assignment = [-1] * J
    for k in range(E):
        s, j = eligible[k]
        if x[e_start + k] == 1:
            assignment[j] = s
    U = 0
    A = 0
    n_f = [0] * F
    for j in range(J):
        s = assignment[j]
        if s >= 0:
            U += value[j]
            A += times[s] - ready[j]
            n_f[flow_of[j]] += 1

    # ---- circulation return arc and residual potentials ----
    v_final = U * 0 + sum(n_f)
    fwd[zr_idx] = mcf.add_edge(ZN, 0, J - v_final, v_final, 0)
    pot = mcf.spfa_pi(pi)
    potentials = [int(pot[v]) for v in range(K)]

    # ---- next-ratio infeasibility cut ----
    cut = None
    if r_star < 1:
        r_plus = rset[best + 1]
        lf2 = lf_for(r_plus)
        ok2, dinic2, ss2 = check_feasible(lf2)
        if ok2:
            raise RuntimeError('next ratio unexpectedly feasible')
        seen = dinic2.reachable(ss2)
        cut = [v for v in range(K) if seen[v]]

    ratio = [r_star.numerator, r_star.denominator]
    return {'predictions': preds, 'ratio': ratio, 'thresholds': thresholds,
            'assignment': assignment, 'utility': U, 'age': A,
            'flow': [int(t) for t in x], 'potential': potentials, 'cut': cut}


def _process(c):
    preds = _predict(c['model'], c['windows'])
    thresholds = probability.window_thresholds(c['stats'], c['windows'])
    thresholds = [int(t) for t in thresholds]
    res = _plan(c, preds, thresholds)
    res['reports'] = metrics.selected_report(
        c['flows'], c['windows'], res['predictions'], res['assignment'])
    out = {'predictions': res['predictions'], 'reports': res['reports'],
           'ratio': res['ratio'], 'thresholds': res['thresholds'],
           'assignment': res['assignment'], 'utility': res['utility'],
           'age': res['age'], 'flow': res['flow'], 'potential': res['potential'],
           'cut': res['cut']}
    return out


def run(raw):
    try:
        if not isinstance(raw, (bytes, bytearray)):
            raw = bytes(raw)
        if len(raw) > MAX_INPUT:
            return {'error': 'invalid'}
        try:
            text = bytes(raw).decode('utf-8')
        except UnicodeDecodeError:
            return {'error': 'invalid'}
        try:
            data = json.loads(text, object_pairs_hook=_pairs_hook,
                              parse_constant=_reject_constant)
        except Exception:
            return {'error': 'invalid'}
        if not _walk_ok(data):
            return {'error': 'invalid'}
        cases = _validate(data)
        if cases is None:
            return {'error': 'invalid'}
        results = [_process(c) for c in cases]
        return {'version': 3, 'results': results}
    except RecursionError:
        return {'error': 'invalid'}
